    semLugar: ['Sem lugar', 'No place'],
    chv_titulo: ['Chaves do serviço', 'Service keys'],
    chv_texto: ['Ligam a IA e a busca para todo mundo que usa o app. Ficam cifradas no servidor: ninguém vê a chave inteira, nem você. Só aparece para a equipe.', 'They turn on AI and search for everyone using the app. Stored encrypted on the server: nobody sees the full key, not even you. Team only.'],
    chv_gemini: ['IA do assistente (Gemini)', 'Assistant AI (Gemini)'], chv_geminiDica: ['Faz o ✦ IA funcionar para quem não tem chave própria.', 'Makes ✦ AI work for people without their own key.'],
    chv_geminiPassos: ['Toque no botão abaixo e entre com a sua conta Google.|Toque em "Create API key" (Criar chave de API).|Escolha um projeto ou crie um novo.|Copie a chave que aparece (começa com AIza).|Volte para cá.', 'Tap the button below and sign in with your Google account.|Tap "Create API key".|Pick or create a project.|Copy the key shown (starts with AIza).|Come back here.'],
    chv_tripadvisor: ['Tripadvisor', 'Tripadvisor'], chv_tripadvisorDica: ['Restaurantes, hotéis e atrações na busca.', 'Restaurants, hotels and attractions in search.'],
    chv_tripadvisorPassos: ['Atenção ao custo: no plano Discover os primeiros 1.000 resultados são grátis (uma vez só); depois, cerca de US$ 0,015 por lugar mostrado. Cada busca do app mostra até 5.|Toque no botão abaixo e, no cartão "Terra API", toque em "Start building for free".|Crie a conta (ou entre) e preencha o projeto: nome GuiaXpert, site solverone.com.br.|No painel (Terra Dashboard), aba Overview, copie o cartão "My API Key".|Volte para cá.', 'Mind the cost: on the Discover plan the first 1,000 results are free (once); then about US$ 0.015 per place shown. Each app search shows up to 5.|Tap the button below and, on the "Terra API" card, tap "Start building for free".|Create the account (or sign in) and fill in the project: name GuiaXpert, site solverone.com.br.|In the Terra Dashboard, Overview tab, copy the "My API Key" card.|Come back here.'],
    chv_foursquare: ['Foursquare', 'Foursquare'], chv_foursquareDica: ['Bares e restaurantes na busca.', 'Bars and restaurants in search.'],
    chv_foursquarePassos: ['Toque no botão abaixo e entre na sua conta.|Crie um projeto (Create a new project).|Dentro do projeto, gere a "Service API Key".|Copie a chave.|Volte para cá.', 'Tap the button below and sign in.|Create a new project.|Inside the project, generate the "Service API Key".|Copy the key.|Come back here.'],
    chv_google: ['Google (Procurar no Google)', 'Google (Search on Google)'], chv_googleDica: ['Opcional. Botão "Procurar no Google" quando a busca não acha.', 'Optional. "Search on Google" button when search finds nothing.'],
    chv_googlePassos: ['Toque no botão abaixo e entre com a sua conta Google.|Crie um projeto e ligue uma conta de faturamento (grátis até 10 mil buscas por mês).|Ative a "Places API (New)".|Em Credenciais, crie uma chave de API e restrinja à Places API (New).|Copie a chave e volte para cá.', 'Tap the button below and sign in with your Google account.|Create a project and attach billing (free up to 10k searches a month).|Enable "Places API (New)".|In Credentials, create an API key restricted to Places API (New).|Copy the key and come back.'],
    chv_ligada: ['Ligada · termina em …{final} · {data}', 'On · ends in …{final} · {data}'], chv_desligada: ['Desligada', 'Off'],
