    chv_salvarCifrada: ['Salvar cifrada', 'Save encrypted'], chv_salvando: ['Salvando com segurança…', 'Saving securely…'],
    chv_salvaTestando: ['Salva. Testando se o serviço aceita…', 'Saved. Testing if the service accepts it…'], chv_aguardando: ['Ligando… pode levar até 1 minuto.', 'Turning on… may take up to 1 minute.'],
    chv_testeOk: ['✓ Funcionou. O serviço aceitou a chave.', '✓ It works. The service accepted the key.'],
    chv_testeSemChave: ['Ainda não ligou. Tente "Testar" de novo em 1 minuto.', 'Not on yet. Try "Test" again in 1 minute.'],
