    chv_testeDemorou: ['⏳ O {servico} demorou demais para responder. A chave pode estar certa: toque em Testar de novo daqui a pouco.', '⏳ {servico} took too long to answer. The key may be fine: tap Test again in a moment.'],
    chv_testeSemCotaGoogle: ['✗ O Google aceitou a chave, mas o projeto dela está sem cota de uso (limite 0). No Google AI Studio, abra a chave → projeto → ative o plano (Set up billing) ou crie a chave num projeto novo.', '✗ Google accepted the key, but its project has no usage quota (limit 0). In Google AI Studio, open the key → project → set up billing, or create the key in a new project.'],
    chv_testeRecusou: ['✗ O {servico} recusou a chave (código {cod}). Confira se copiou inteira e se o serviço está ativado na conta.', '✗ {servico} rejected the key (code {cod}). Check you copied all of it and the service is enabled.'],
    chv_seguranca: ['A chave vai protegida (HTTPS) e fica cifrada no servidor. O app e o celular nunca guardam a chave. Para mexer, pedimos que você confirme que é você.', 'The key travels protected (HTTPS) and is stored encrypted on the server. The app and phone never keep it. To change it, we ask you to confirm it is you.'],
    chv_confirmeTitulo: ['Confirme que é você', 'Confirm it is you'], chv_confirmeTexto: ['Por segurança, para mexer nas chaves confirme a conta {email}.', 'For security, to change keys confirm the account {email}.'],
    chv_ouCodigo: ['Não tem senha ou não lembra?', 'No password or forgot it?'], chv_receberCodigo: ['Receber e-mail de confirmação', 'Get a confirmation email'],
    chv_codigoEnviado: ['Mandamos um e-mail para {email}. Se tiver um código de 6 números, digite abaixo. Se tiver só o botão "Sign in", toque nele: o app abre já confirmado e reabre esta tela para você colar a chave de novo.', 'We emailed {email}. If it has a 6-digit code, type it below. If it only has a "Sign in" button, tap it: the app opens already confirmed and reopens this screen so you can paste the key again.'],
    chv_senhaErrada: ['Senha não confere. Tente de novo ou use o código por e-mail.', 'Wrong password. Try again or use the email code.'], chv_codigoErrado: ['Código não confere ou venceu.', 'Code is wrong or expired.'],
